sys_script_client.script:
function onLoad() {
    var consumerSysId = g_form.getValue('consumer');
    //g_form.addInfoMessage("Consumer Sys ID: " + consumerSysId);

    if (!consumerSysId) return; // stop if field is empty

    var ga = new GlideAjax('GetKycDetails');
    ga.addParam('sysparm_name', 'getKYCDetails');
    ga.addParam('sysparm_consumer_sysid', consumerSysId); // ✅ match parameter name

    ga.getXMLAnswer(function(response) {
        if (response) {
            try {
                var kyc = JSON.parse(response);

                g_form.setValue('x_1811084_diya_c_0_aadhar_number', kyc.aadhar_no);
                g_form.setValue('x_1811084_diya_c_0_pan_number', kyc.pan_no);
                g_form.setValue('x_1811084_diya_c_0_driving_license_number', kyc.driving_license_no);
                g_form.setValue('x_1811084_diya_c_0_dl_issued_date', kyc.dl_issued_d);
                g_form.setValue('x_1811084_diya_c_0_dl_expiry_date', kyc.dl_expiry_d);

                // Make fields read-only
                g_form.setReadOnly('x_1811084_diya_c_0_aadhar_number', true);
                g_form.setReadOnly('x_1811084_diya_c_0_pan_number', true);
                g_form.setReadOnly('x_1811084_diya_c_0_driving_license_number', true);
                g_form.setReadOnly('x_1811084_diya_c_0_dl_issued_date', true);
                g_form.setReadOnly('x_1811084_diya_c_0_dl_expiry_date', true);

                // g_form.addInfoMessage("KYC details loaded successfully.");
            } catch (e) {
                g_form.addErrorMessage("Error parsing KYC details: " + e.message);
            }
        } else {
            g_form.addInfoMessage("No KYC data found for this consumer.");
        }
    });
}
